import json,urllib.request,urllib.error,pathlib
cfg=json.loads(pathlib.Path('/home/appontrack/ontrack-voice-link/config.json').read_text())
token=cfg['token']
base='https://api.github.com/repos/OnTrack-Development/OnTrack-voice/actions/runs/'
targets=[(41945362481,'aa376ea9ba95'),(41945512666,'e44cd89fe3c7')]
out=[]
for run,sha in targets:
 h={'Authorization':'Bearer '+token,'Accept':'application/vnd.github+json','User-Agent':'OnTrack-Responsive-CI-Cleanup'}
 try:
  with urllib.request.urlopen(urllib.request.Request(base+str(run),headers=h),timeout=8) as r:
   row=json.load(r)
  if not str(row.get('head_sha','')).startswith(sha):
   out.append({'run':run,'result':'sha_mismatch_not_touched'});continue
  if row.get('status')=='completed':
   out.append({'run':run,'result':'already_completed'});continue
  request=urllib.request.Request(base+str(run)+'/cancel',data=b'',headers=h,method='POST')
  with urllib.request.urlopen(request,timeout=8) as r:
   out.append({'run':run,'result':'cancel_requested','http':r.status})
 except urllib.error.HTTPError as e:out.append({'run':run,'result':'not_cancelled','http':e.code})
 except Exception as e:out.append({'run':run,'result':'error','type':type(e).__name__})
print(json.dumps(out))
